verus! {

fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
    ensures
        // The result vector has exactly 10 elements
        res.len() == 10,
        // And for each index k in [0,10), res[k] equals arr[k]
        forall|k: usize| k < 10 ==> res[k] == arr[k]
{
    let mut res: Vec<bool> = Vec::new();
    let mut i: usize = 0;
    // We will iterate i from 0 up to 10, each time pushing arr[i] into res
    while i < 10
        invariant
            // i never exceeds 10
            i <= 10,
            // res.len() tracks i
            res.len() == i,
            // For all k < i, we've already copied arr[k] into res[k]
            forall|k: usize| k < i ==> res[k] == arr[k],
        decreases 10 - i
    {
        // Read the next element
        let v: bool = arr[i];
        // Append it
        res.push(v);
        // After push, res.len() == i+1 and the new element is correct
        assert(res.len() == i + 1);
        assert(res[i] == v);
        // Move to the next index
        i = i + 1;
    }
    // At this point i == 10 and res.len() == 10
    res
}

} // end verus!

